-- Splits the single description_short text per lab_parameter into three
-- reading levels (Anfänger/Standard/Profi), selectable in the parameter
-- detail view. description_level2 keeps the existing description_short
-- wording; description_level1/3 are new.

alter table lab_parameters add column if not exists description_level1 text not null default '';
alter table lab_parameters add column if not exists description_level2 text not null default '';
alter table lab_parameters add column if not exists description_level3 text not null default '';

update lab_parameters set description_level2 = description_short;

update lab_parameters as p
set description_level1 = v.level1,
    description_level3 = v.level3
from (values
  ('erythrocytes', 'Rote Blutzellen bringen Sauerstoff von der Lunge zu deinem ganzen Körper.', 'Zelluläres Kompartiment des Sauerstofftransports; Anzahl variiert mit Höhe, Hydratationsstatus und Erythropoetin-Aktivität, wird gemeinsam mit Hb/Hkt/Indizes zur Anämie-Klassifikation (mikro-/normo-/makrozytär) herangezogen.'),
  ('hemoglobin', 'Hämoglobin ist der rote Farbstoff im Blut, der den Sauerstoff festhält und transportiert.', 'Eisenhaltiges Transportprotein in Erythrozyten; zentraler Parameter der Anämiediagnostik, interpretiert gemeinsam mit MCV/MCH zur Ursachenabklärung (z. B. Eisen-, Vitamin-B12-Mangel, chronische Erkrankung).'),
  ('hematocrit', 'Zeigt, wie viel Prozent deines Blutes aus roten Blutzellen besteht.', 'Volumenanteil der zellulären Blutbestandteile am Gesamtblutvolumen; eng korreliert mit Hb, zusätzlich beeinflusst durch das Plasmavolumen (z. B. Dehydratation, Schwangerschaft).'),
  ('mcv', 'Verrät, ob deine roten Blutzellen eher klein, normal oder groß sind.', 'Mittleres Erythrozytenvolumen; Leitparameter zur morphologischen Anämie-Einteilung (mikro-, normo-, makrozytär), z. B. mikrozytär bei Eisenmangel, makrozytär bei B12-/Folsäuremangel.'),
  ('mch', 'Zeigt, wie viel roter Blutfarbstoff im Durchschnitt in einer einzelnen Blutzelle steckt.', 'Mittlerer Hämoglobingehalt pro Erythrozyt; korreliert meist mit dem MCV, ergänzt die morphologische Anämie-Differenzierung.'),
  ('mchc', 'Sagt aus, wie konzentriert der rote Blutfarbstoff in den Blutzellen ist.', 'Hämoglobinkonzentration bezogen auf das Erythrozytenvolumen; erniedrigt v. a. bei hypochromen Anämien (z. B. Eisenmangel, Thalassämie).'),
  ('rdw', 'Zeigt, wie unterschiedlich groß deine roten Blutzellen zueinander sind.', 'Streuungsmaß der Erythrozytengröße (Anisozytose); erhöht u. a. bei beginnendem Eisen-, Folsäure- oder B12-Mangel, hilfreich zur Abgrenzung gemischter Anämieformen.'),
  ('leukocytes', 'Weiße Blutzellen sind die Abwehrzellen deines Körpers gegen Krankheitserreger.', 'Gesamtzahl der Leukozyten als Summe aller Subpopulationen; Erhöhung (Leukozytose) bzw. Erniedrigung (Leukopenie) erfordert ein Differenzialblutbild zur weiteren Einordnung.'),
  ('platelets', 'Blutplättchen sorgen dafür, dass eine Wunde aufhört zu bluten.', 'Thrombozytenzahl; zentral für die primäre Hämostase, Interpretation im Kontext von Blutungsneigung (Thrombozytopenie) oder Thromboserisiko (Thrombozytose).'),
  ('mpv', 'Zeigt die durchschnittliche Größe deiner Blutplättchen.', 'Mittleres Thrombozytenvolumen; erhöht bei gesteigertem Thrombozytenumsatz (jüngere, größere Plättchen), ergänzt die Thrombozytenzahl bei der Ursachenabklärung von Thrombozytopenien.'),
  ('neutrophils', 'Die häufigste Abwehrzelle, sie kämpft vor allem gegen Bakterien.', 'Größte Granulozyten-Subpopulation; Anstieg typisch bei bakteriellen Infekten und Stressreaktionen, Abfall (Neutropenie) erhöht das Infektionsrisiko.'),
  ('lymphocytes', 'Abwehrzellen, die besonders gegen Viren helfen und sich an Erreger "erinnern".', 'Umfasst T-, B- und NK-Zellen; relative/absolute Lymphozytose typisch bei viralen Infekten, Lymphopenie u. a. bei Immunsuppression oder schweren Akutinfekten.'),
  ('monocytes', 'Aufräumzellen, die kranke Zellen und Erregerreste beseitigen.', 'Vorläufer der Gewebemakrophagen; Erhöhung bei chronischen Entzündungen, bestimmten Infektionen (z. B. Tuberkulose) und in der Erholungsphase nach Neutropenie.'),
  ('eosinophils', 'Diese Zellen sind besonders aktiv bei Allergien und Parasiten.', 'Assoziiert mit Typ-2-Immunantworten; Eosinophilie typisch bei Allergien, Asthma, Parasitosen und bestimmten Medikamentenreaktionen.'),
  ('basophils', 'Die seltenste Abwehrzellart, beteiligt an allergischen Reaktionen.', 'Enthalten histaminhaltige Granula; Beteiligung an IgE-vermittelten Reaktionen, selten isoliert erhöht (z. B. bei myeloproliferativen Erkrankungen).'),
  ('quick_inr', 'Zeigt, wie schnell dein Blut gerinnen kann, wenn eine Wunde entsteht.', 'Prüft den extrinsischen Gerinnungsweg (Faktoren II, V, VII, X); die INR standardisiert die Messung v. a. zur Steuerung einer Vitamin-K-Antagonisten-Therapie.'),
  ('ptt', 'Ein weiterer Test dafür, wie gut dein Blut gerinnt.', 'Prüft den intrinsischen und gemeinsamen Gerinnungsweg; verlängert bei Faktorenmangel, Hemmkörpern oder unter Heparintherapie.'),
  ('fibrinogen', 'Ein Eiweiß im Blut, das für die Wundheilung wichtig ist und bei Entzündungen ansteigt.', 'Akute-Phase-Protein und Vorstufe von Fibrin; erhöht bei Entzündung/Infektion, erniedrigt bei Verbrauchskoagulopathie (z. B. DIC) oder Leberfunktionsstörung.'),
  ('d_dimer', 'Zeigt an, ob sich im Körper kürzlich ein Blutgerinnsel aufgelöst hat.', 'Fibrin-Spaltprodukt; hohe Sensitivität, aber geringe Spezifität für Thrombose/Embolie – v. a. zum Ausschluss bei niedriger klinischer Wahrscheinlichkeit geeignet.'),
  ('got_ast', 'Ein Eiweiß, das ins Blut gelangt, wenn Leber- oder Muskelzellen beschädigt sind.', 'Mitochondriales/zytoplasmatisches Enzym, nicht leberspezifisch (auch Herz-/Skelettmuskel); Beurteilung meist im Verhältnis zu ALT (De-Ritis-Quotient).'),
  ('gpt_alt', 'Ein Leber-Eiweiß, das ansteigt, wenn Leberzellen gestresst oder verletzt sind.', 'Überwiegend zytoplasmatisches, leberspezifischeres Enzym als AST; sensitiver Marker für Hepatozytenschädigung, z. B. bei Fettleber, Virushepatitis oder Medikamententoxizität.'),
  ('ggt', 'Ein Leberwert, der oft ansteigt bei Problemen mit der Galle oder durch Alkohol.', 'Membranständiges Enzym der Gallengangsepithelien und Hepatozyten; empfindlicher, aber unspezifischer Marker für Cholestase, Alkoholkonsum und Enzyminduktion durch Medikamente.'),
  ('alp', 'Ein Enzym aus Leber und Knochen, das bei Gallenstau oder Knochenumbau ansteigt.', 'Isoenzyme aus Leber, Knochen und Plazenta; isolierte Erhöhung erfordert Differenzierung (z. B. via GGT) zwischen cholestatischer und ossärer Ursache.'),
  ('bilirubin_total', 'Der Abbaustoff der roten Blutzellen, der bei Gelbsucht die Haut gelb färbt.', 'Summe aus unkonjugiertem und konjugiertem Bilirubin; Fraktionierung nötig zur Unterscheidung prähepatischer (Hämolyse), hepatischer und posthepatischer (Cholestase) Ursachen.'),
  ('albumin', 'Das wichtigste Eiweiß im Blut, es hält z. B. Wasser in den Blutgefäßen.', 'Von der Leber synthetisiertes Transport- und onkotisches Protein; erniedrigt bei chronischer Leberinsuffizienz, Malnutrition, nephrotischem Syndrom oder chronischer Entzündung.'),
  ('creatinine', 'Ein Abfallstoff der Muskeln, den gesunde Nieren zuverlässig aus dem Blut filtern.', 'Muskelmassenabhängiger Filtrationsmarker; Grundlage der eGFR-Berechnung, wenig sensitiv für eine frühe Nierenfunktionseinschränkung.'),
  ('urea', 'Ein weiterer Abfallstoff, der zeigt, wie gut die Nieren arbeiten.', 'Endprodukt des Proteinstoffwechsels; beeinflusst durch Eiweißzufuhr, Hydratation und GI-Blutungen, daher weniger spezifisch als Kreatinin für die Nierenfunktion.'),
  ('egfr', 'Schätzt, wie gut deine Nieren das Blut pro Minute reinigen.', 'Aus Kreatinin (ggf. Cystatin C), Alter und Geschlecht geschätzte Filtrationsleistung; zentrale Kenngröße zur CKD-Stadieneinteilung nach KDIGO.'),
  ('uric_acid', 'Ein Abbaustoff, der bei zu hohem Wert Gelenkschmerzen (Gicht) auslösen kann.', 'Endprodukt des Purinstoffwechsels; Hyperurikämie erhöht das Risiko für Gichtarthritis und Uratnephropathie, oft ernährungs- und stoffwechselassoziiert.'),
  ('sodium', 'Ein Salz im Blut, das den Wasserhaushalt deines Körpers steuert.', 'Zentraler Bestimmungsfaktor der extrazellulären Osmolalität; Dysnatriämien sind meist Ausdruck eines gestörten Wasser-, nicht primär Natriumhaushalts.'),
  ('potassium', 'Ein Mineralstoff, der wichtig für Herzschlag und Muskeln ist.', 'Überwiegend intrazelluläres Kation; Dyskaliämien können akut lebensbedrohliche Herzrhythmusstörungen verursachen, daher engmaschige Kontrolle bei Abweichungen.'),
  ('calcium', 'Ein Mineralstoff für starke Knochen, der auch Muskeln und Nerven steuert.', 'Regulation über Parathormon und Vitamin D; Interpretation sollte das Albumin (korrigiertes Calcium) berücksichtigen, da ein relevanter Anteil proteingebunden zirkuliert.'),
  ('chloride', 'Ein Salz, das zusammen mit Natrium den Säure-Basen-Haushalt ausbalanciert.', 'Wichtigstes extrazelluläres Anion; hilfreich zur Einordnung von Säure-Basen-Störungen gemeinsam mit Bikarbonat und Anionenlücke.'),
  ('glucose', 'Der Traubenzucker im Blut, der deinem Körper Energie liefert.', 'Nüchternglukose als Screening-Parameter für Prädiabetes/Diabetes mellitus gemäß ADA/WHO-Grenzwerten; ergänzend HbA1c und ggf. oGTT.'),
  ('hba1c', 'Zeigt den durchschnittlichen Blutzucker der letzten paar Monate.', 'Glykiertes Hämoglobin, spiegelt die mittlere Glukoseexposition der letzten ca. 8–12 Wochen; zentral für Diagnose und Verlaufskontrolle des Diabetes mellitus.'),
  ('insulin', 'Ein Hormon, das den Zucker aus dem Blut in die Zellen schleust.', 'Von Betazellen sezerniertes Hormon; gemeinsam mit der Nüchternglukose zur Beurteilung einer Insulinresistenz (z. B. HOMA-IR) nutzbar.'),
  ('cholesterol_total', 'Ein Fettstoff im Blut, der in "guten" und "schlechten" Formen vorkommt.', 'Summe aus LDL-, HDL- und VLDL-Cholesterin; als alleiniger Wert nur begrenzt aussagekräftig, das kardiovaskuläre Risiko wird über das Gesamtlipidprofil bewertet.'),
  ('ldl', 'Das "schlechte" Cholesterin, das sich in Blutgefäßen ablagern kann.', 'Zentraler kausaler Risikofaktor für Atherosklerose; Zielwerte richten sich nach dem individuellen kardiovaskulären Gesamtrisiko (z. B. SCORE2).'),
  ('hdl', 'Das "gute" Cholesterin, das Ablagerungen aus den Gefäßen abtransportiert.', 'Vermittelt den reversen Cholesterintransport; niedrige Werte gelten als unabhängiger kardiovaskulärer Risikofaktor, hohe Werte sind nicht per se kausal protektiv.'),
  ('triglycerides', 'Neutralfette im Blut, die stark von der Ernährung beeinflusst werden.', 'Nüchternwert empfohlen; deutlich erhöhte Werte (> 500 mg/dl) bergen zusätzlich ein Pankreatitisrisiko, oft assoziiert mit metabolischem Syndrom.'),
  ('ferritin', 'Zeigt, wie viel Eisen dein Körper gespeichert hat.', 'Akute-Phase-Protein und Eisenspeicherparameter zugleich; kann bei Entzündung trotz Eisenmangel falsch-hoch ausfallen, ggf. gemeinsam mit CRP interpretieren.'),
  ('serum_iron', 'Das Eisen, das gerade im Blut unterwegs ist – schwankt stark im Tagesverlauf.', 'Hohe intraindividuelle Tagesvariabilität; allein wenig aussagekräftig, sollte gemeinsam mit Ferritin, Transferrin und Transferrinsättigung beurteilt werden.'),
  ('transferrin', 'Ein Transporter, der Eisen im Blut von einem Ort zum anderen bringt.', 'Hepatisch synthetisiertes Transportprotein; steigt kompensatorisch bei Eisenmangel, sinkt bei Entzündung oder Leberinsuffizienz (negatives Akute-Phase-Protein).'),
  ('transferrin_saturation', 'Zeigt, wie voll die Eisen-Transporter im Blut gerade beladen sind.', 'Verhältnis von Serumeisen zur Transferrin-Bindungskapazität; sensitiver Frühindikator für funktionellen oder absoluten Eisenmangel.'),
  ('vitamin_d', 'Ein Vitamin, das vor allem über Sonnenlicht auf der Haut gebildet wird und für die Knochen wichtig ist.', '25-OH-Vitamin-D als Speicherform mit längster Halbwertszeit; relevant für Kalziumhomöostase, Knochenstoffwechsel und Immunmodulation.'),
  ('vitamin_b12', 'Ein Vitamin, das für Nerven und Blutbildung wichtig ist – kommt vor allem in tierischen Lebensmitteln vor.', 'Kobalamin, essenziell für DNA-Synthese und Myelinisierung; Mangel äußert sich makrozytär-hyperchrom und/oder neurologisch, die Aufnahme hängt vom Intrinsic Factor ab.'),
  ('folic_acid', 'Ein B-Vitamin, das wichtig für Zellteilung und Blutbildung ist.', 'Kofaktor der DNA-Synthese; Mangel führt zu makrozytärer Anämie, in der Schwangerschaft zusätzlich relevant für die Neuralrohrentwicklung.'),
  ('vitamin_b6', 'Ein B-Vitamin, das beim Eiweißstoffwechsel und den Nerven hilft.', 'Kofaktor (als PLP) zahlreicher Aminosäure- und Neurotransmitter-Stoffwechselwege; Mangel selten isoliert, häufiger im Kontext allgemeiner Malnutrition.'),
  ('zinc', 'Ein Spurenelement, das Immunsystem, Wundheilung und Haut unterstützt.', 'Kofaktor zahlreicher Enzyme (u. a. Zink-Finger-Proteine); Mangel u. a. bei chronisch-entzündlichen Darmerkrankungen, Alkoholismus oder unausgewogener veganer Ernährung.'),
  ('magnesium', 'Ein Mineralstoff, der Muskeln, Nerven und Herz unterstützt.', 'Kofaktor über 300 enzymatischer Reaktionen; Mangel begünstigt Muskelkrämpfe und Herzrhythmusstörungen, der Serumwert spiegelt die intrazellulären Speicher nur unzureichend wider.'),
  ('selenium', 'Ein Spurenelement mit Schutzfunktion für Zellen, wichtig auch für die Schilddrüse.', 'Bestandteil der Selenoproteine (u. a. Glutathionperoxidasen, Dejodasen); relevant für den Schilddrüsenhormon-Metabolismus und antioxidativen Zellschutz.'),
  ('tsh', 'Das Steuerhormon, das der Schilddrüse sagt, wie viel sie arbeiten soll.', 'Hypophysäres Steuerhormon, sensitivster Screening-Parameter der Schilddrüsenfunktion; supprimiert bei Hyperthyreose, erhöht bei primärer Hypothyreose.'),
  ('ft3', 'Das aktive Schilddrüsenhormon, das direkt im Körper wirkt.', 'Freies, biologisch aktives Trijodthyronin; v. a. relevant bei Verdacht auf T3-Hyperthyreose oder zur Verlaufskontrolle bei bekannter Schilddrüsenerkrankung.'),
  ('ft4', 'Das andere aktive Schilddrüsenhormon, das der Körper teils in T3 umwandelt.', 'Freies Thyroxin, Hauptsekretionsprodukt der Schilddrüse und Prohormon für T3; gemeinsam mit TSH Basisdiagnostik der Schilddrüsenfunktion.'),
  ('testosterone', 'Das wichtigste männliche Geschlechtshormon, kommt auch bei Frauen in kleiner Menge vor.', 'Überwiegend testikulär (bzw. adrenal/ovariell) produziertes Androgen; Tagesrhythmik beachten (Morgenwert), das Gesamttestosteron kann durch die SHBG-Bindung verzerrt sein.'),
  ('estradiol', 'Das wichtigste weibliche Geschlechtshormon, schwankt bei Frauen stark im Zyklus.', 'Potentestes natürliches Östrogen; die Interpretation bei Frauen erfordert Kenntnis der Zyklusphase bzw. des Menopausenstatus.'),
  ('progesterone', 'Ein Hormon, das nach dem Eisprung ansteigt und wichtig für eine Schwangerschaft ist.', 'Sekretionsprodukt des Corpus luteum (bzw. der Plazenta); Bestimmung meist zyklustagbezogen zur Beurteilung der Lutealphase oder Ovulation.'),
  ('lh', 'Ein Steuerhormon aus dem Gehirn, das den Eisprung bzw. die Hormonproduktion der Keimdrüsen anstößt.', 'Hypophysäres Gonadotropin; pulsatile Sekretion, bei Frauen mit charakteristischem präovulatorischem Peak, Basis der Fertilitätsdiagnostik.'),
  ('fsh', 'Ein weiteres Steuerhormon aus dem Gehirn für die Eizell- bzw. Spermienreifung.', 'Hypophysäres Gonadotropin; bei Frauen zentraler Marker der ovariellen Reserve, perimenopausal ansteigend.'),
  ('cortisol', 'Das wichtigste Stresshormon, das morgens am höchsten ist.', 'Glukokortikoid mit ausgeprägter zirkadianer Rhythmik; eine Einzelmessung ist nur im Kontext der Tageszeit interpretierbar, bei Verdacht auf Dysfunktion sind dynamische Tests (z. B. Dexamethason-Hemmtest) erforderlich.'),
  ('dhea_s', 'Ein Vorstufenhormon aus der Nebenniere, das mit dem Alter abnimmt.', 'Sulfatierte Form des DHEA mit stabiler Serumkonzentration (kein Tagesrhythmus); grober Marker der adrenalen Androgenproduktion.'),
  ('crp', 'Ein Wert, der schnell ansteigt, wenn im Körper eine Entzündung aktiv ist.', 'Hepatisches Akute-Phase-Protein, Anstieg innerhalb von 6–12 h nach Entzündungsreiz; unspezifisch, aber sensitiv – hs-CRP wird zusätzlich in der kardiovaskulären Risikostratifizierung genutzt.'),
  ('bsg', 'Ein älterer, langsamerer Entzündungstest.', 'Indirektes Maß der Erythrozytensedimentation, abhängig von Fibrinogen/Immunglobulinen; reagiert träger als CRP, ergänzend bei chronisch-entzündlichen/rheumatologischen Fragestellungen.'),
  ('procalcitonin', 'Hilft zu unterscheiden, ob eine Infektion eher von Bakterien verursacht wird.', 'Steigt relativ spezifisch bei bakteriellen (v. a. systemischen) Infektionen an, im Gegensatz zu viralen Infekten; unterstützt Sepsis-Diagnostik und Antibiotikasteuerung.'),
  ('troponin', 'Ein Eiweiß aus dem Herzmuskel, das bei einem Herzinfarkt ansteigt.', 'Hochsensitiver, kardiospezifischer Marker der Myokardnekrose; die Verlaufskinetik (Anstieg/Abfall) ist essenziell zur Abgrenzung akuter von chronischer Erhöhung.'),
  ('nt_probnp', 'Ein Hormon aus dem Herzen, das bei Herzschwäche ansteigt.', 'Vom gedehnten Myokard sezerniertes natriuretisches Peptid; Alter, Nierenfunktion und BMI beeinflussen den Wert, wichtig zur Diagnose/zum Ausschluss einer Herzinsuffizienz.'),
  ('ck', 'Ein Enzym aus Muskeln, das bei Muskel- oder Herzschäden ansteigt.', 'Unspezifischer Marker der Muskelzellschädigung (Skelett- und Herzmuskel); bei kardialem Verdacht heute meist durch Troponin abgelöst, weiterhin relevant für Myopathien/Rhabdomyolyse.'),
  ('psa', 'Ein Wert aus der Prostata, der zur Verlaufskontrolle genutzt wird, aber kein alleiniger Krebsbeweis ist.', 'Organspezifisch, nicht tumorspezifisch; auch bei benigner Prostatahyperplasie oder Prostatitis erhöht, der Verlauf/die Kinetik (PSA-Velocity) ist oft aussagekräftiger als der Einzelwert.'),
  ('ca_125', 'Ein Wert, der vor allem zur Verlaufskontrolle bei bestimmten Erkrankungen des Bauchraums genutzt wird.', 'Wenig spezifischer Tumormarker; auch bei Endometriose, Menstruation oder Peritonealreizung erhöht, primär zur Verlaufsbeurteilung bei bekanntem Ovarialkarzinom geeignet.'),
  ('cea', 'Ein unspezifischer Marker, der vor allem bei der Nachsorge von Darmkrebs genutzt wird.', 'Nicht zum Screening geeignet; bei Rauchern sowie diversen benignen Erkrankungen erhöht, primäre Bedeutung in der postoperativen Verlaufskontrolle kolorektaler Karzinome.'),
  ('afp', 'Ein Marker, der vor allem bei Leberkrebs verfolgt wird und in der Schwangerschaft natürlich erhöht ist.', 'Physiologisch erhöht in der Fetalperiode und Schwangerschaft; bei Erwachsenen v. a. relevant zur Verlaufskontrolle des hepatozellulären Karzinoms und bei Keimzelltumoren.'),
  ('hiv', 'Ein Test, der prüft, ob eine HIV-Infektion vorliegt.', 'Kombinierter Antikörper-/p24-Antigen-Test (4. Generation); reaktive Befunde erfordern eine Bestätigungstestung, das diagnostische Fenster nach Exposition ist zu beachten.'),
  ('hepatitis_b', 'Ein Test, der prüft, ob eine Hepatitis-B-Infektion vorliegt oder vorlag.', 'Serologisches Panel (u. a. HBsAg, Anti-HBc, Anti-HBs) unterscheidet akute/chronische Infektion, durchgemachte Infektion und Impfschutz.'),
  ('hepatitis_c', 'Ein Test, der prüft, ob eine Hepatitis-C-Infektion vorliegt oder vorlag.', 'Anti-HCV-Antikörpertest als Screening; ein reaktiver Befund erfordert eine HCV-RNA-Bestätigung zur Unterscheidung zwischen ausgeheilter und aktiver Infektion.'),
  ('ana', 'Ein Screening-Test auf Antikörper, die den eigenen Körper angreifen können.', 'Screening-Marker für systemische Autoimmunerkrankungen (u. a. Lupus); niedrigtitrige positive Befunde sind auch bei Gesunden möglich, positive Befunde erfordern Titer- und Musteranalyse plus Subtyp-Antikörper.'),
  ('rheumatoid_factor', 'Ein Antikörper, der bei rheumatischen Gelenkerkrankungen oft erhöht ist.', 'Autoantikörper gegen das Fc-Fragment von IgG; mäßige Sensitivität/Spezifität für rheumatoide Arthritis, auch bei anderen Erkrankungen oder Gesunden positiv möglich.'),
  ('anti_ccp', 'Ein spezifischerer Antikörper-Test für rheumatische Gelenkerkrankungen.', 'Antikörper gegen citrullinierte Peptide; höhere Spezifität als der Rheumafaktor für rheumatoide Arthritis, kann Jahre vor Symptombeginn positiv sein.'),
  ('ige_total', 'Die Gesamtmenge eines Antikörpertyps, der bei Allergien eine Rolle spielt.', 'Unspezifischer Marker der atopischen Gesamtdisposition; auch bei Parasitosen erhöht, für sich genommen nicht diagnostisch – spezifisches IgE ist aussagekräftiger.'),
  ('tryptase', 'Ein Wert, der bei starken allergischen Reaktionen stark ansteigt.', 'Mastzell-spezifisches Enzym; ein akuter Anstieg (Bestimmung 1–4 h nach dem Ereignis) stützt die Diagnose Anaphylaxie, dauerhaft erhöhte Basalwerte können auf eine Mastzellerkrankung hinweisen.'),
  ('ecp', 'Zeigt, wie aktiv die allergische Entzündung gerade ist.', 'Freigesetzt aus aktivierten Eosinophilen; Marker der eosinophilen Entzündungsaktivität, u. a. zur Verlaufsbeurteilung bei Asthma/Atopie genutzt, wenig standardisiert.'),
  ('basophil_activation_test', 'Ein Zelltest, der zeigt, wie stark bestimmte Abwehrzellen auf ein Allergen reagieren.', 'Durchflusszytometrischer Funktionstest der basophilen Aktivierbarkeit; ergänzt spezifisches IgE u. a. bei diskrepanten Befunden oder Verdacht auf Nahrungsmittel-/Medikamentenallergie.'),
  ('ige_bet_v_1', 'Prüft speziell auf das Hauptallergen der Birke, um eine echte Birkenpollenallergie von einer Kreuzreaktion zu unterscheiden.', 'Komponentenaufgelöste Diagnostik (CRD) für das Majorallergen Bet v 1; hilft, eine genuine Birkensensibilisierung von einer profilin-/PR-10-vermittelten Kreuzreaktivität (z. B. mit Nahrungsmitteln) abzugrenzen.'),
  ('ige_ara_h_2', 'Prüft ein Erdnuss-Eiweiß, das auf ein höheres Risiko für starke Reaktionen hinweisen kann.', 'Speicherprotein-Komponente mit hoher Assoziation zu schweren, systemischen Reaktionen; hilfreich zur Risikoeinschätzung bei Erdnusssensibilisierung.'),
  ('ige_phl_p_1', 'Prüft das Hauptallergen der Gräser, um eine echte Gräserallergie von einer Kreuzreaktion zu unterscheiden.', 'Majorallergen-Komponente der Süßgräser; unterstützt die Unterscheidung einer genuinen Gräserpollenallergie von polysensibilisierten Kreuzreaktionsmustern.'),
  ('skin_prick_test', 'Ein Allergietest, bei dem ein Tropfen Allergenlösung auf die Haut kommt und leicht angeritzt wird.', 'In-vivo-Sofortreaktionstest; die Quaddelgröße nach 15–20 Min. korreliert mit dem Sensibilisierungsgrad, muss stets mit der Anamnese abgeglichen werden.'),
  ('intracutaneous_test', 'Ein empfindlicherer Allergietest, bei dem das Allergen unter die Haut gespritzt wird.', 'Höhere Sensitivität, aber geringere Spezifität als der Pricktest; v. a. bei unklarem Pricktest oder in der Insektengiftallergie-Diagnostik eingesetzt.'),
  ('patch_test', 'Ein Test für Kontaktallergien, bei dem Pflaster mit Testsubstanzen mehrere Tage auf der Haut bleiben.', 'Prüft eine T-Zell-vermittelte Typ-IV-Reaktion (Spättyp); Ablesung nach 48 und 72 h, Standard zur Abklärung von Kontaktekzemen.'),
  ('nasal_provocation', 'Das Allergen wird gezielt in die Nase gegeben, um eine Allergie zu bestätigen.', 'In-vivo-Provokationstest bei diskrepanten Ergebnissen von Anamnese, Haut- und IgE-Test; nahezu Goldstandard-Methode für die allergische Rhinitis.'),
  ('bronchial_provocation', 'Das Allergen wird gezielt eingeatmet, um zu prüfen, ob die Atemwege allergisch reagieren.', 'Provokation zur Objektivierung einer allergischen Atemwegsreaktion; wird unter kontrollierten Bedingungen mit Lungenfunktionsmonitoring durchgeführt, u. a. bei der Abklärung von Berufsasthma.'),
  ('oral_food_challenge', 'Ein Nahrungsmittel wird unter ärztlicher Aufsicht gegessen, um eine Allergie sicher zu bestätigen oder auszuschließen.', 'Goldstandard der Nahrungsmittelallergie-Diagnostik; titrierte, ärztlich überwachte Verabreichung (idealerweise doppelblind-plazebokontrolliert) zur definitiven Diagnosesicherung.'),
  ('urine_ph', 'Zeigt, wie sauer oder basisch dein Urin gerade ist.', 'Beeinflusst durch Ernährung, Stoffwechsellage und Infektionen; z. B. alkalischer pH bei ureasebildenden Harnwegsinfekt-Erregern.'),
  ('urine_specific_gravity', 'Zeigt, wie konzentriert dein Urin gerade ist – hängt stark davon ab, wie viel du getrunken hast.', 'Grobes Maß der renalen Konzentrationsfähigkeit; niedrige Werte bei hoher Flüssigkeitszufuhr oder Diabetes insipidus, hohe Werte bei Dehydratation.'),
  ('urine_protein', 'Zeigt, ob Eiweiß über den Urin ausgeschieden wird, was ein früher Hinweis auf die Nieren sein kann.', 'Semiquantitativer Streifentest, v. a. sensitiv für Albumin; positive Befunde erfordern Bestätigung/Quantifizierung (z. B. Albumin-Kreatinin-Ratio).'),
  ('urine_glucose', 'Zeigt Zucker im Urin, was meist erst bei sehr hohem Blutzucker vorkommt.', 'Tritt auf, wenn die renale Reabsorptionskapazität (Nierenschwelle) überschritten wird; klassisch bei unzureichend eingestelltem Diabetes mellitus.'),
  ('urine_ketones', 'Zeigt Abbauprodukte aus dem Fettstoffwechsel im Urin, z. B. beim Fasten oder bei wenig Kohlenhydraten.', 'Hinweis auf gesteigerte Lipolyse/Ketogenese; relevant zur Erkennung einer diabetischen Ketoazidose, auch physiologisch bei Fasten oder Low-Carb-Ernährung.'),
  ('urine_nitrite', 'Zeigt Bakterien im Urin an, die typisch für eine Blasenentzündung sind.', 'Nitrit entsteht durch bakterielle Reduktion von Nitrat; positiv v. a. bei Enterobacteriaceae, ein negativer Befund schließt einen HWI aber nicht sicher aus.'),
  ('urine_leukocytes', 'Weiße Blutzellen im Urin, die auf eine Entzündung der Harnwege hinweisen.', 'Leukozyturie als Hinweis auf ein entzündliches Geschehen der Harnwege; im Kontext von Nitrit und Klinik zur HWI-Diagnostik zu interpretieren.'),
  ('urine_blood', 'Rote Blutzellen im Urin, z. B. durch eine Infektion, Steine oder andere Ursachen.', 'Mikro-/Makrohämaturie erfordert eine Abklärung der Quelle (glomerulär vs. postrenal); persistierende asymptomatische Hämaturie bedarf weiterführender Diagnostik.'),
  ('urine_microalbumin', 'Prüft kleinste Eiweißmengen im Urin, die sehr früh auf beginnende Nierenschäden hinweisen können, z. B. bei Diabetes.', 'Sensitivster Frühmarker der diabetischen/hypertensiven Nephropathie; Beurteilung idealerweise über die Albumin-Kreatinin-Ratio im Spontanurin.'),
  ('creatinine_clearance', 'Misst über gesammelten Urin, wie gut die Nieren Abfallstoffe herausfiltern.', 'Funktionelle GFR-Schätzung über 24-h-Sammelurin; anfällig für Sammelfehler, wird zunehmend durch die formelbasierte eGFR ersetzt, bleibt aber bei extremen Körpermaßen relevant.'),
  ('urine_culture_result', 'Ein Labortest, der prüft, ob und welche Bakterien im Urin wachsen.', 'Quantitative bakteriologische Kultur mit Keimzahlbestimmung und Erregeridentifikation; Grundlage für Antibiogramm und gezielte Antibiotikatherapie bei HWI.'),
  ('urine_drug_screen', 'Ein Schnelltest, der auf Rückstände bestimmter Substanzen im Urin prüft.', 'Immunologischer Schnelltest mit Cutoff-Werten; positive Befunde sind bei forensischer/arbeitsmedizinischer Relevanz durch Bestätigungsanalytik (z. B. GC-MS) zu verifizieren.'),
  ('occult_blood', 'Ein Test, der nicht sichtbares Blut im Stuhl nachweist – ein früher Hinweis, den man ernst nehmen sollte.', 'Immunologischer fäkaler Okkultbluttest (iFOBT); etabliertes Screening-Instrument für kolorektale Karzinome/Polypen, ein positiver Befund erfordert eine Koloskopie.'),
  ('calprotectin', 'Ein Wert im Stuhl, der zeigt, ob im Darm gerade eine Entzündung aktiv ist.', 'Neutrophilen-assoziiertes Protein; hilft, entzündliche Darmerkrankungen (CED) von funktionellen Beschwerden wie dem Reizdarmsyndrom zu unterscheiden.'),
  ('helicobacter_pylori_antigen', 'Ein Test, der prüft, ob ein bestimmtes Magenbakterium vorhanden ist.', 'Nicht-invasiver Nachweis von H.-pylori-Antigen im Stuhl; hohe Sensitivität/Spezifität, geeignet zur Erst- und Eradikationskontrolle (PPI-Pause vor Testung beachten).'),
  ('parasites_worm_eggs', 'Eine mikroskopische Untersuchung auf Darmparasiten oder deren Eier.', 'Mikroskopischer Nachweis von Parasiten/Eiern; aufgrund intermittierender Ausscheidung ggf. Untersuchung mehrerer Proben an unterschiedlichen Tagen sinnvoll.'),
  ('microbiome_analysis', 'Beschreibt, welche Bakterien in deinem Darm leben und wie vielfältig sie sind.', 'Sequenzierungsbasierte Zusammensetzungsanalyse der Darmmikrobiota; klinische Interpretierbarkeit und Standardisierung derzeit limitiert, der Befund ist meist deskriptiv ohne etablierte Referenzbereiche.'),
  ('ige_grass_pollen', 'Zeigt, ob dein Immunsystem allergisch auf Gräserpollen reagiert.', 'Spezifischer IgE-Nachweis gegen Gräserpollen; ein positiver Wert zeigt eine Sensibilisierung, nicht zwingend eine klinisch relevante Allergie – muss immer mit den Symptomen abgeglichen werden.'),
  ('ige_rye_pollen', 'Zeigt, ob dein Immunsystem allergisch auf Roggenpollen reagiert.', 'Spezifischer IgE-Nachweis gegen Roggenpollen; ein positiver Wert zeigt eine Sensibilisierung, nicht zwingend eine klinisch relevante Allergie – muss immer mit den Symptomen abgeglichen werden.'),
  ('ige_birch_pollen', 'Zeigt, ob dein Immunsystem allergisch auf Birkenpollen reagiert.', 'Spezifischer IgE-Nachweis gegen Birkenpollen; ein positiver Wert zeigt eine Sensibilisierung, nicht zwingend eine klinisch relevante Allergie – muss immer mit den Symptomen abgeglichen werden.'),
  ('ige_hazel_pollen', 'Zeigt, ob dein Immunsystem allergisch auf Haselpollen reagiert.', 'Spezifischer IgE-Nachweis gegen Haselpollen; ein positiver Wert zeigt eine Sensibilisierung, nicht zwingend eine klinisch relevante Allergie – muss immer mit den Symptomen abgeglichen werden.'),
  ('ige_alder_pollen', 'Zeigt, ob dein Immunsystem allergisch auf Erlenpollen reagiert.', 'Spezifischer IgE-Nachweis gegen Erlenpollen; ein positiver Wert zeigt eine Sensibilisierung, nicht zwingend eine klinisch relevante Allergie – muss immer mit den Symptomen abgeglichen werden.'),
  ('ige_mugwort', 'Zeigt, ob dein Immunsystem allergisch auf Beifuß reagiert.', 'Spezifischer IgE-Nachweis gegen Beifuß; ein positiver Wert zeigt eine Sensibilisierung, nicht zwingend eine klinisch relevante Allergie – muss immer mit den Symptomen abgeglichen werden.'),
  ('ige_ragweed', 'Zeigt, ob dein Immunsystem allergisch auf Ambrosia reagiert.', 'Spezifischer IgE-Nachweis gegen Ambrosia; ein positiver Wert zeigt eine Sensibilisierung, nicht zwingend eine klinisch relevante Allergie – muss immer mit den Symptomen abgeglichen werden.'),
  ('ige_dust_mite_pter', 'Zeigt, ob dein Immunsystem allergisch auf die Hausstaubmilbe (D. pteronyssinus) reagiert.', 'Spezifischer IgE-Nachweis gegen die Hausstaubmilbe (D. pteronyssinus); ein positiver Wert zeigt eine Sensibilisierung, nicht zwingend eine klinisch relevante Allergie – muss immer mit den Symptomen abgeglichen werden.'),
